\set ON_ERROR_STOP on
-- Run in one transaction, with legacy-schema.sql generated by migrate-existing.sh.
CREATE SCHEMA stage7_expected;
\i legacy-schema.sql
DO $$ BEGIN
  IF EXISTS (
    WITH actual AS (SELECT table_name,column_name,data_type,udt_name,is_nullable,character_maximum_length,numeric_precision,numeric_scale
      FROM information_schema.columns WHERE table_schema='public'),
    expected AS (SELECT table_name,column_name,data_type,udt_name,is_nullable,character_maximum_length,numeric_precision,numeric_scale
      FROM information_schema.columns WHERE table_schema='stage7_expected')
    SELECT 1 FROM ((SELECT * FROM expected EXCEPT SELECT * FROM actual)
      UNION ALL (SELECT * FROM actual EXCEPT SELECT * FROM expected)) diff
  ) THEN RAISE EXCEPTION 'Schema differs from V1: inspect types, nullability and columns before baseline'; END IF;
  IF EXISTS (
    WITH actual AS (SELECT c.relname,t.contype,replace(pg_get_constraintdef(t.oid),'public.','') def FROM pg_constraint t
      JOIN pg_class c ON c.oid=t.conrelid JOIN pg_namespace n ON c.relnamespace=n.oid WHERE n.nspname='public'),
    expected AS (SELECT c.relname,t.contype,replace(pg_get_constraintdef(t.oid),'stage7_expected.','') def FROM pg_constraint t
      JOIN pg_class c ON c.oid=t.conrelid JOIN pg_namespace n ON c.relnamespace=n.oid WHERE n.nspname='stage7_expected')
    SELECT 1 FROM ((SELECT * FROM expected EXCEPT SELECT * FROM actual)
      UNION ALL (SELECT * FROM actual EXCEPT SELECT * FROM expected)) diff
  ) THEN RAISE EXCEPTION 'Constraints differ from V1; reconcile before baseline'; END IF;
END $$;
-- Data/trigger checks are the identical guard executed by V2 before any schema change.
\i receiving-guard.sql
ROLLBACK;
